async function (vars) {
    vars.MasterdataBucketResult = (await getBucket({
        ParentId: vars.RootBucket.Id,
        Key: "Masterdata"
    })).value;
},
async function (vars) {
    if (vars.MasterdataBucketResult.length === 0) {
        vars.MasterdataBucket = await createBucket({
            ParentId: vars.RootBucket.Id,
            Key: "Masterdata",
            Roles: vars.BucketRoles.map(c => ({ RoleId: c.Id })),
            Name: vars.AppName + " Masterdata " + vars.AppType
        });
    } else {
        vars.MasterdataBucket = vars.MasterdataBucketResult[0];
    }
},
